// ESP8266 keeps its existing manual alarms without reserving RAM for an unsupported list.
#ifdef ESP8266
constexpr uint8_t MAX_PHONE_ALARMS = 0;
#else
constexpr uint8_t MAX_PHONE_ALARMS = 32;
#endif
constexpr size_t PHONE_LIST_MAX_BODY = 12000;

struct PhoneAlarm {
  char label[129] = "";
  uint16_t wakeMinute = 0;
  uint8_t weekdays = 0; // Monday in bit 0; zero is one upcoming, device-dated occurrence.
  bool enabled = false;
  uint32_t date = 0, lastDate = 0; // Resolved and consumed by WLED, never supplied by Clock.
};

inline bool phoneTextSpace(char c) { return c == ' ' || c == '\t' || c == '\r' || c == '\n'; }

// Normalize only bounded text representations; unsupported Clock values are rejected,
// not treated as disabled/empty. This lets the Shortcut forward properties without Ifs.
inline bool phoneLowerText(const char* source, char* output, size_t capacity) {
  if (!source) return false;
  const size_t length = strnlen(source, capacity);
  if (length >= capacity) return false;
  size_t first = 0, last = length;
  while (first < last && phoneTextSpace(source[first])) ++first;
  while (last > first && phoneTextSpace(source[last - 1])) --last;
  size_t written = 0;
  for (size_t i = first; i < last; ++i) {
    const char c = source[i];
    output[written++] = c >= 'A' && c <= 'Z' ? c + ('a' - 'A') : c;
  }
  output[written] = '\0';
  return true;
}

// Native booleans and their normal Clock text representations have identical meaning.
inline bool parsePhoneEnabled(JsonVariantConst value, bool& enabled) {
  if (value.is<bool>()) { enabled = value.as<bool>(); return true; }
  if (value.is<uint8_t>() && value.as<uint8_t>() <= 1) { enabled = value.as<uint8_t>() != 0; return true; }
  char text[16];
  if (!value.is<const char*>() || !phoneLowerText(value.as<const char*>(), text, sizeof(text))) return false;
  for (const char* yes : {"true", "yes", "ja", "1", "on", "enabled"}) {
    if (!strcmp(text, yes)) { enabled = true; return true; }
  }
  for (const char* no : {"false", "no", "nein", "0", "off", "disabled"}) {
    if (!strcmp(text, no)) { enabled = false; return true; }
  }
  return false;
}

// Clock's Time is formatted, not scheduled, by the client: exactly a local HH:mm.
inline bool parsePhoneTime(JsonVariantConst value, uint16_t& minute) {
  if (!value.is<const char*>()) return false;
  const char* text = value.as<const char*>();
  if (strnlen(text, 6) != 5 || text[2] != ':') return false;
  for (unsigned i : {0U, 1U, 3U, 4U}) if (text[i] < '0' || text[i] > '9') return false;
  const unsigned hour = (text[0] - '0') * 10 + text[1] - '0', part = (text[3] - '0') * 10 + text[4] - '0';
  if (hour > 23 || part > 59) return false;
  minute = hour * 60 + part;
  return true;
}

// Map a single, already-normalized weekday token to WLED's Monday-based bitmask.
inline uint8_t phoneWeekday(const char* text) {
  static const char* const NAMES[7][6] = {
    {"monday", "montag", "mon", "mo", nullptr, nullptr},
    {"tuesday", "dienstag", "tue", "tues", "di", nullptr},
    {"wednesday", "mittwoch", "wed", "mi", nullptr, nullptr},
    {"thursday", "donnerstag", "thu", "thur", "thurs", "do"},
    {"friday", "freitag", "fri", "fr", nullptr, nullptr},
    {"saturday", "samstag", "sonnabend", "sat", "sa", nullptr},
    {"sunday", "sonntag", "sun", "so", nullptr, nullptr}
  };
  for (unsigned day = 0; day < 7; ++day) {
    for (const char* name : NAMES[day]) if (name && !strcmp(text, name)) return uint8_t(1U << day);
  }
  return 0;
}

// Recognize English/German Clock weekday lists and summaries without asking the
// Shortcut to calculate masks. Unknown tokens fail the complete snapshot safely.
inline bool parsePhoneRepeatText(const char* source, uint8_t& weekdays) {
  char text[257];
  if (!phoneLowerText(source, text, sizeof(text))) return false;
  weekdays = 0;
  if (!text[0]) return true;
  for (const char* none : {"never", "none", "no repeat", "does not repeat", "nie", "keine", "keine wiederholung"}) {
    if (!strcmp(text, none)) return true;
  }
  for (const char* daily : {"daily", "every day", "everyday", "täglich", "jeden tag"}) {
    if (!strcmp(text, daily)) { weekdays = 127; return true; }
  }
  for (const char* work : {"weekdays", "every weekday", "every weekdays", "wochentags", "werktags"}) {
    if (!strcmp(text, work)) { weekdays = 31; return true; }
  }
  for (const char* weekend : {"weekends", "every weekend", "wochenende", "am wochenende"}) {
    if (!strcmp(text, weekend)) { weekdays = 96; return true; }
  }
  size_t read = 0, written = 0;
  while (text[read]) {
    char c = text[read++];
    if (c == '.') {
      // A terminal abbreviation dot is valid; punctuation inside a name is not.
      if (text[read] && !phoneTextSpace(text[read]) && text[read] != ',' && text[read] != ';') return false;
      continue;
    }
    if (phoneTextSpace(c) || c == ',' || c == ';') c = ' ';
    text[written++] = c;
  }
  text[written] = '\0';
  char* position = text;
  bool prefix = false;
  while (*position) {
    while (*position == ' ') ++position;
    if (!*position) break;
    char* token = position;
    while (*position && *position != ' ') ++position;
    if (*position) *position++ = '\0';
    if (!strcmp(token, "and") || !strcmp(token, "und")) {
      if (!weekdays || prefix) return false;
      prefix = true;
      continue;
    }
    if (!strcmp(token, "every") || !strcmp(token, "jeden") || !strcmp(token, "am")) {
      if (prefix) return false;
      prefix = true;
      continue;
    }
    const uint8_t day = phoneWeekday(token);
    if (!day) return false;
    weekdays |= day;
    prefix = false;
  }
  return weekdays && !prefix;
}

// Arrays, summary text and an explicit weekday mask share one validated representation.
inline bool parsePhoneRepeat(JsonVariantConst value, uint8_t& weekdays) {
  weekdays = 0;
  if (value.isNull()) return true; // An explicit null/empty array means no repeat; missing fields are rejected below.
  if (value.is<const char*>()) return parsePhoneRepeatText(value.as<const char*>(), weekdays);
  if (value.is<uint8_t>() && value.as<uint8_t>() <= 127) { weekdays = value.as<uint8_t>(); return true; }
  if (!value.is<JsonArrayConst>() || value.size() > 7) return false;
  for (JsonVariantConst item : value.as<JsonArrayConst>()) {
    uint8_t days;
    if (!item.is<const char*>() || !parsePhoneRepeatText(item.as<const char*>(), days) || (!days && value.size() != 1)) return false;
    weekdays |= days;
  }
  return true;
}

// Require all four Clock properties; a missing value must not masquerade as a disabled alarm.
inline bool parsePhoneAlarm(JsonObjectConst root, PhoneAlarm& alarm, const char*& error) {
  if (root.size() != 4 || !root.containsKey("label") || !root.containsKey("enabled") ||
      !root.containsKey("time") || !root.containsKey("repeat")) { error = "invalid_alarm_fields"; return false; }
  const char* label = root["label"].isNull() ? "" : root["label"].as<const char*>();
  if (!validLabel(label)) { error = "invalid_alarm_label"; return false; }
  memmove(alarm.label, label, strnlen(label, sizeof(alarm.label)) + 1); // Validated size; also safe for a borrowed self-label.
  if (!parsePhoneEnabled(root["enabled"], alarm.enabled)) { error = "invalid_alarm_enabled"; return false; }
  if (!parsePhoneTime(root["time"], alarm.wakeMinute)) { error = "invalid_alarm_time"; return false; }
  if (!parsePhoneRepeat(root["repeat"], alarm.weekdays)) { error = "invalid_alarm_repeat"; return false; }
  alarm.date = alarm.lastDate = 0;
  return true;
}

// Labels are not identifiers: two Clock alarms can share a label or a wake time.
// Equivalent snapshots keep their semantics regardless of Find Alarms' ordering.
inline int comparePhoneAlarm(const PhoneAlarm& a, const PhoneAlarm& b) {
  if (a.wakeMinute != b.wakeMinute) return a.wakeMinute < b.wakeMinute ? -1 : 1;
  if (a.weekdays != b.weekdays) return a.weekdays < b.weekdays ? -1 : 1;
  const int label = strcmp(a.label, b.label);
  if (label) return label;
  return int(a.enabled) - int(b.enabled);
}

// Bounded insertion sort makes snapshot comparison independent of Clock's list order.
inline void sortPhoneAlarms(PhoneAlarm* alarms, uint8_t count) {
  for (uint8_t i = 1; i < count; ++i) {
    const PhoneAlarm value = alarms[i];
    uint8_t position = i;
    while (position && comparePhoneAlarm(value, alarms[position - 1]) < 0) { alarms[position] = alarms[position - 1]; --position; }
    alarms[position] = value;
  }
}

// The public list can be sent back as a new snapshot; device-owned dates/markers
// stay private to NVS and cannot be reset by an iPhone upload.
inline void serializePhoneAlarm(JsonObject root, const PhoneAlarm& alarm, bool stored = false) {
  root["label"] = alarm.label;
  root["enabled"] = alarm.enabled;
  if (stored) {
    root["wakeMinute"] = alarm.wakeMinute;
    root["weekdays"] = alarm.weekdays;
    root["date"] = alarm.date;
    root["lastDate"] = alarm.lastDate;
  } else {
    char time[6];
    snprintf(time, sizeof(time), "%02u:%02u", unsigned(alarm.wakeMinute / 60), unsigned(alarm.wakeMinute % 60));
    root["time"] = time;
    static const char* const DAYS[] = {"Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"};
    JsonArray repeat = root.createNestedArray("repeat");
    for (unsigned day = 0; day < 7; ++day) if (alarm.weekdays & (1U << day)) repeat.add(DAYS[day]);
  }
}

// Defensively decode the canonical NVS schedule, including device-owned execution dates.
inline bool parseStoredPhoneAlarm(JsonObjectConst root, PhoneAlarm& alarm, const char*& error) {
  uint32_t value;
  if (root.size() != 6 || !root["label"].is<const char*>() || !validLabel(root["label"].as<const char*>()) ||
      !root["enabled"].is<bool>() || !number(root["wakeMinute"], 0, 1439, value)) { error = "sync_configuration_unreadable"; return false; }
  const char* label = root["label"];
  memmove(alarm.label, label, strnlen(label, sizeof(alarm.label)) + 1);
  alarm.enabled = root["enabled"];
  alarm.wakeMinute = value;
  if (!number(root["weekdays"], 0, 127, value)) { error = "sync_configuration_unreadable"; return false; }
  alarm.weekdays = value;
  if (!number(root["date"], 0, 20991231, alarm.date) || (alarm.date && !validDate(alarm.date)) ||
      (!alarm.weekdays && !alarm.date) || (alarm.weekdays && alarm.date) ||
      !number(root["lastDate"], 0, 20991231, alarm.lastDate) || (alarm.lastDate && !validDate(alarm.lastDate))) {
    error = "sync_configuration_unreadable"; return false;
  }
  return true;
}

